import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaSignInAlt, FaUser, FaLock, FaSchool } from 'react-icons/fa';

function Login() {
  const [name, setName] = useState('');
  const [role, setRole] = useState('parent');
  const [schoolId, setSchoolId] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const validateForm = () => {
    const newErrors = {};

    if (!name.trim()) newErrors.name = 'Name is required';
    if (!schoolId.trim()) newErrors.schoolId = 'School ID is required';
    if (!email.trim()) newErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(email)) newErrors.email = 'Email is invalid';
    if (!password) newErrors.password = 'Password is required';
    else if (password.length < 6) newErrors.password = 'Password must be at least 6 characters';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    // Simulate login - replace with actual API call
    const user = {
      name,
      role,
      schoolId,
      email,
      id: 1,
      createdAt: new Date().toLocaleString()
    };

    // Store user in localStorage
    localStorage.setItem('user', JSON.stringify(user));

    // Redirect based on role
    if (role === 'admin') {
      navigate('/admin');
    } else {
      navigate('/dashboard');
    }
  };

  return (
    <div className="py-5">
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-6 col-lg-5">
            <div className="card-custom">
              <div className="card-header text-center">
                <h3><FaSignInAlt className="me-2" /> Login to Portal</h3>
                <p className="mb-0">Access your school facility dashboard</p>
              </div>
              <div className="card-body p-4">
                <form onSubmit={handleSubmit}>
                  <div className="mb-3">
                    <label className="form-label">
                      <FaUser className="me-2" /> Full Name
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg"
                      placeholder="Enter your name"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                    />
                    {errors.name && <div className="text-danger small mt-1">{errors.name}</div>}
                  </div>

                  <div className="mb-3">
                    <label className="form-label">
                      <FaSchool className="me-2" /> School ID
                    </label>
                    <input
                      type="text"
                      className="form-control form-control-lg"
                      placeholder="Enter school ID"
                      value={schoolId}
                      onChange={(e) => setSchoolId(e.target.value)}
                    />
                    {errors.schoolId && <div className="text-danger small mt-1">{errors.schoolId}</div>}
                  </div>

                  <div className="mb-3">
                    <label className="form-label">Role</label>
                    <select
                      className="form-select form-select-lg"
                      value={role}
                      onChange={(e) => setRole(e.target.value)}
                    >
                      <option value="parent">Parent</option>
                      <option value="teacher">Teacher</option>
                      <option value="admin">Admin</option>
                    </select>
                  </div>

                  <div className="mb-3">
                    <label className="form-label">
                      <FaLock className="me-2" /> Email Address
                    </label>
                    <input
                      type="email"
                      className="form-control form-control-lg"
                      placeholder="Enter email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                    />
                    {errors.email && <div className="text-danger small mt-1">{errors.email}</div>}
                  </div>

                  <div className="mb-4">
                    <label className="form-label">
                      <FaLock className="me-2" /> Password
                    </label>
                    <input
                      type="password"
                      className="form-control form-control-lg"
                      placeholder="Enter password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                    {errors.password && <div className="text-danger small mt-1">{errors.password}</div>}
                  </div>

                  <div className="d-grid gap-2">
                    <button type="submit" className="btn btn-custom btn-lg">
                      <FaSignInAlt className="me-2" /> Login
                    </button>
                  </div>

                  <div className="text-center mt-4">
                    <p className="mb-0">
                      Don't have an account? 
                      <Link to="/register" className="text-primary ms-2">Register Here</Link>
                    </p>
                  </div>
                </form>
              </div>
            </div>

            {/* Demo Accounts */}
            <div className="card-custom mt-4">
              <div className="card-header">
                <h5 className="mb-0">Demo Accounts</h5>
              </div>
              <div className="card-body">
                <div className="mb-2">
                  <strong>Admin:</strong> admin@school.com | Password: admin123
                </div>
                <div className="mb-2">
                  <strong>Parent:</strong> parent@school.com | Password: parent123
                </div>
                <div>
                  <strong>Teacher:</strong> teacher@school.com | Password: teacher123
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Login;
